import logging
from enum import Enum

from .adapters import CmDataRepositorySoapAdapter
from .parser import (
    process_response,
    remove_namespaces,
    convert_xml_to_dict,
    convert_metadata_response
)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CmDataRepositoryWebServiceAPI:
    """
    CMDataRepositoryAPI
    - http://belk.netact.noklab.net/N1X_TRUNK/topic/cm_data_repository_webservice_api/concepts/about_this_document-d14e13.html
    - https://confluence.int.net.nokia.com/display/OSSRD/CM+Web+Service+Interface
    """

    OPERATIONS = Enum('operation', {'create': 'CREATE', 'delete': 'DELETE', 'modify': 'UPDATE'})  # type: ignore[misc]

    def __init__(self, web_url, username, password):
        self.soap_api = CmDataRepositorySoapAdapter(web_url, username, password)

    # --- Methods for creating objects defined by API ---

    def prepare_managed_object(self, meta_class, meta_version, mo_id, operation='UPDATE', parameters=None):
        """
        Create ManagedObject.

        :param string meta_class: e.g. 'com.nokia.mrbts:MRBTS' (can be obtained using get_managed_objects)
        :param string meta_version: e.g. 'MRBTS17A_1701_003' (can be obtained using get_managed_objects)
        :param string mo_id: e.g. 'PLMN-PLMN/MRBTS-123456'
        :param dict(string, string) parameters: MO parameters e.g. {'btsName': 'my awesome bts')
        :param string operation: CREATE or DELETE or UPDATE (corresponds to 'Change to Modify')
        :return: managed object
        :rtype: CmDataRepositorySoapAdapter.model_type_factory.ManagedObject
        """
        operation = self.OPERATIONS(operation.upper()).value
        parameters = parameters or {}
        managed_object = self.soap_api.model_type_factory.ManagedObject(metaClass=meta_class,
                                                                        metaVersion=meta_version,
                                                                        moId=mo_id,
                                                                        operation=operation,
                                                                        _value_1=self._create_value_1(parameters))
        return managed_object

    @classmethod
    def _create_value_1(cls, parameters):
        """
        Create _value_1 list (zeep library format) from MO parameters dictionary.

        Info about _value_1: http://docs.python-zeep.org/en/master/datastructures.html?highlight=value_#xsd-choice

        Example output
        **************
        ::

            '_value_1': [
                {
                    'p': {
                        '_value_1': '1500',
                        'name': 'maxNtpTimeError'
                    }
                },
                {
                    'scalarList': {
                        'p': [
                            {
                                '_value_1': '2.2.2.2',
                                'name': None
                            },
                            {
                                '_value_1': '1.1.1.1',
                                'name': None
                            }
                        ],
                        'name': 'ntpServerIpAddrList'
                    }
                }
            ]

        :param dict(string, (string|list)) parameters: MO parameters e.g.
            {'maxNtpTimeError': '1500', 'ntpServerIpAddrList': ['2.2.2.2', '1.1.1.1']}
        :return: _value_1
        :rtype: list
        """
        _value_1 = []
        for name, value in parameters.items():
            if isinstance(value, list):
                if not value:
                    raise ValueError(f'Empty list is not allowed for {name!r} parameter')
                elif isinstance(value[0], dict):
                    _value_1.append(cls._convert_to_struct_list(name, value))
                else:
                    _value_1.append(cls._convert_to_scalar_list(name, value))
            else:
                _value_1.append({'p': {'_value_1': value, 'name': name}})
        return _value_1

    @staticmethod
    def _convert_to_struct_list(name, values):
        """

        Example output
        **************
        ::

            {
                'structList': {
                    'item': [
                        {
                            'p': [
                                {
                                    '_value_1': '0',
                                    'name': 'blacklistTopo'
                                },
                                {
                                    '_value_1': '65535',
                                    'name': 'freqEutra'
                                }
                            ]
                        },
                        {
                            'p': [
                                {
                                    '_value_1': '1',
                                    'name': 'blacklistTopo'
                                },
                                {
                                    '_value_1': '65535',
                                    'name': 'freqEutra'
                                }
                            ]
                        }
                    ],
                    'name': 'blacklistHoL'
                }
            }

        :param string name: e.g. 'blacklistHoL'
        :param list values: e.g.
            [{'blacklistTopo': '0', 'freqEutra': '65535'}, {'blacklistTopo': '1', 'freqEutra': '65535'}]
        :return: structList
        :rtype: dict
        """
        return {
            'structList': {'item': [{'p': [{'_value_1': v, 'name': k} for k, v in value.items()]} for value in values],
                           'name': name}}

    @staticmethod
    def _convert_to_scalar_list(name, values):
        """

        Example output
        **************
        ::

            {
                'scalarList': {
                    'p': [
                        {
                            '_value_1': '2.2.2.2',
                            'name': None
                        },
                        {
                            '_value_1': '1.1.1.1',
                            'name': None
                        }
                    ],
                    'name': 'ntpServerIpAddrList'
                }
            }

        :param string name: e.g. 'ntpServerIpAddrList'
        :param list values: e.g. ['2.2.2.2', '1.1.1.1']
        :return: scalarList
        :rtype: dict
        """
        return {'scalarList': {'p': [{'_value_1': value, 'name': None} for value in values], 'name': name}}

    #  --- API methods ---

    #  Managed objects

    def create_managed_objects(self, conf_id, managed_object):
        """
        Create new managed objects in given plan. Example output:

        Example output
        **************
        ::

            [{
                'errorCode': 'OK',
                'errorCause': None,
                'moLite': {
                    'moId': 'PLMN-PLMN/MRBTS-123456',
                    'metaClass': 'com.nokia.mrbts:MRBTS',
                    'metaVersion': 'MRBTS17A_1701_003'
                }
            }, ...]

        :param (int|string) conf_id: target plan id can be obtained from get_configurations
            or create_configuration
        :param (ManagedObject | list(ManagedObject)) managed_object:
            (can be obtained from prepare_managed_object)
            If this parameter is a list - a list of dicts will be returned.
            If this parameter is a dict - a single dict will be returned.
        :return: MO Lite(s)
        :rtype: (list | dict)
        """
        require_unique = not isinstance(managed_object, list)
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        response = self.soap_api.service.createManagedObjects(configuration=configuration,
                                                              managedObject=managed_object)
        return process_response(response,
                                result_path='result.batchItemMOLiteResult',
                                return_path='moLite',
                                require_unique=require_unique)

    def delete_managed_objects(self, conf_id, mo_id):
        """
        Delete managed objects by given conf_id and mo_id(s). Example output:

        Example output
        **************
        ::

            [{
                'errorCode': 'OK',
                'errorCause': None,
                'moLite': {
                    'moId': 'PLMN-PLMN/MRBTS-123456',
                    'metaClass': 'com.nokia.mrbts:MRBTS',
                    'metaVersion': 'MRBTS17A_1701_003'
                }
            }, ...]

        :param (int|string) conf_id: can be obtained from get_configurations
            or create_configuration
        :param (list(string) | string) mo_id: e.g.
            'PLMN-PLMN/MRBTS-123456' or ['PLMN-PLMN/MRBTS-123456', 'PLMN-PLMN/MRBTS-456789']
            If this parameter is a list - a list of dicts will be returned.
            If this parameter is a string - a single dict will be returned.
        :return: MO Lite(s)
        :rtype: (list | dict)
        """
        if isinstance(mo_id, list):
            require_unique = False
        else:
            # deleteManagedObjects requires a list of mo_ids,
            # so in case of one mo_id, it's necessary to convert it to list
            mo_id = [mo_id]
            require_unique = True
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        response = self.soap_api.service.deleteManagedObjects(configuration=configuration, moId=mo_id)
        return process_response(response,
                                result_path='result.batchItemMOLiteResult',
                                return_path='moLite',
                                require_unique=require_unique)

    def get_managed_objects(self, conf_id, mo_id):
        """
        Get managed objects by conf_id and mo_id(s). Example output:

        Example output
        **************
        ::

            [{
                'errorCode': 'OK',
                'errorCause': None,
                'managedObject': {
                    'metaClass': 'com.nokia.mrbts:MRBTS',
                    'metaVersion': 'MRBTS17A_1701_003',
                    'moId': 'PLMN-PLMN/MRBTS-123456',
                    'operation': 'UPDATE',
                    '_value_1': [
                        {
                            'p': {
                                '_value_1': 'olsniewajaca bazoweczka',
                                'name': 'btsName'
                            }
                        }
                    ]
                }
            }, ...]

        :param (int|string) conf_id: can be obtained from get_configurations
            or create_configuration
        :param (list(string) | string) mo_id: e.g.
            'PLMN-PLMN/MRBTS-123456' or ['PLMN-PLMN/MRBTS-123456', 'PLMN-PLMN/MRBTS-456789']
            If this parameter is a list - a list of dicts will be returned.
            If this parameter is a string - a single dict will be returned.
        :return: MO(s)
        :rtype: (list | dict)
        """
        if isinstance(mo_id, list):
            require_unique = False
        else:
            # getManagedObjects requires a list of mo_ids,
            # so in case of one mo_id it's necessary to convert it to list
            mo_id = [mo_id]
            require_unique = True
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        response = self.soap_api.service.getManagedObjects(configuration=configuration, moId=mo_id)
        return process_response(response,
                                result_path='result.batchItemMOResult',
                                return_path='managedObject',
                                require_unique=require_unique)

    def update_managed_objects(self, conf_id, managed_object):
        """
        Update given managed object in given plan. Example output:

        Example output
        **************
        ::

            [{
                'errorCode': 'OK',
                'errorCause': None,
                'moLite': {
                    'moId': 'PLMN-PLMN/MRBTS-123456',
                    'metaClass': 'com.nokia.mrbts:MRBTS',
                    'metaVersion': 'MRBTS17A_1701_003'
                }
            }, ...]

        :param (int|string) conf_id: target plan id can be obtained from get_configurations
            or create_configuration
        :param (ManagedObject | list(ManagedObject)) managed_object:
            (can be obtained from prepare_managed_object)
            If this parameter is a list - a list of dicts will be returned.
            If this parameter is a dict - a single dict will be returned.
        :return: MO Lite(s)
        :rtype: (list | dict)
        """
        require_unique = not isinstance(managed_object, list)
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        response = self.soap_api.service.updateManagedObjects(configuration=configuration,
                                                              managedObject=managed_object)
        return process_response(response,
                                result_path='result.batchItemMOLiteResult',
                                return_path='moLite',
                                require_unique=require_unique)

    #  Configurations

    def create_configuration(self, configuration_type, name, description=None):
        """
        Create configuration (most commonly PLANs). Example output:

        Example output
        **************
        ::

            {
                'configuration': {
                    'confId': '411'
                }
            }

        :param configuration_type: e.g. 'PLAN'
        :param name: e.g. 'my awesome new plan'
        :param description: e.g. 'the most vital plan on NetAct'
        :return: configuration
        :rtype: dict(string, dict)
        """
        # 'configuration' argument is required to create ConfigurationHeader
        # but it is empty and unused, since conf_id is unknown before configuration is created
        configuration = self.soap_api.model_type_factory.Configuration()
        configuration_header = self.soap_api.model_type_factory.ConfigurationHeader(configuration=configuration,
                                                                                    type=configuration_type,
                                                                                    name=name,
                                                                                    description=description)
        response = self.soap_api.service.createConfiguration(configuration_header)
        return process_response(response)

    def delete_configuration(self, conf_id):
        """
        Delete configuration with given confId. Example output:

        Example output
        **************
        ::

            {
                'configuration': {
                    'confId': '411'
                }
            }

        :param (int|string) conf_id: can be obtained from get_configurations or create_configuration
        :return: configuration
        :rtype: dict(string, dict)
        """
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        response = self.soap_api.service.deleteConfiguration(configuration=configuration)
        return process_response(response)

    def get_configurations(self, filter_value=None, filter_type='name'):
        """
        Get configuration filtered by name or by id or by type.
        If no filter is specified - a list of all configurations will be returned. Example output:

        Example output
        **************
        ::

            [{
                'configuration': {
                    'confId': '230'
                },
                'type': 'PLAN',
                'name': 'New Plan (230)',
                'description': 'New plan.'
            }, ...]

        :param string filter_value: e.g. 'New Plan (230)' for 'name' filter,
            or '230' for 'id' filter, or 'PLAN' for 'type' filter
        :param string filter_type: 'type' or 'name' or 'id' ('name' by default)
        :return: configuration header(s)
        :rtype: (list | dict(string, dict))
        """
        configuration_filter = None
        if filter_value:
            if filter_type == 'name':
                configuration_filter = self.soap_api.operations_type_factory.ConfigurationNameFilter(name=filter_value)
            elif filter_type == 'id':
                configuration_filter = self.soap_api.operations_type_factory.ConfigurationIdFilter(id=filter_value)
            elif filter_type == 'type':
                configuration_filter = self.soap_api.operations_type_factory.ConfigurationTypeFilter(type=filter_value)

        # configurations should have unique names and IDs, so if a filter is applied
        # it's pointless to return a list
        require_unique = True if configuration_filter else False
        response = self.soap_api.service.getConfigurations(filter=configuration_filter)
        return process_response(response, result_path='result.configurationHeader',
                                require_unique=require_unique)

    def update_configuration(self, conf_id, configuration_type, name, description=None):
        """
        Update configuration with given confId. Example output:

        Example output
        **************
        ::

            {
                'configuration': {
                    'confId': '411'
                }
            }

        :param (int|string) conf_id: can be obtained from get_configurations or create_configuration
        :param string configuration_type: e.g. 'PLAN'
        :param string name: e.g. 'my awesome new plan'
        :param string description: e.g. 'the most vital plan on NetAct'
        :return: configuration
        :rtype: dict(string, dict)
        """
        configuration = self.soap_api.model_type_factory.Configuration(conf_id)
        configuration_header = self.soap_api.model_type_factory.ConfigurationHeader(configuration=configuration,
                                                                                    type=configuration_type,
                                                                                    name=name,
                                                                                    description=description)
        response = self.soap_api.service.updateConfiguration(configuration_header)
        return process_response(response)

    def get_metadata_relationship_defs(self, relationship_id):
        """
        Get managed object(s) metadata, where metadata means the relationship between CM managed object classes.
        The relationship includes a name, source object, and target object.

        Example output
        **************
        ::

            {
                'relationshipId': 'CHILD_NRBTS',
                'sourceMetaClass': 'com.nokia.srbts:MRBTS',
                'targetMetaClass': 'com.nokia.srbts.nrbts:NRBTS'
            }

        :param string relationship_id: e.g. ``CHILD_NRBTS``.
            If set to ``None``, all relationship definitions are returned.
        :return: Managed object(s) relationship definitions
        :rtype: dict | list(dict)
        """
        require_unique = True if relationship_id is not None else False
        metadata_request_filter = self.soap_api.operations_type_factory.RelationshipDefIdFilter(
            relationshipId=relationship_id
        )
        response = self.soap_api.service.getMetadata(metadata_request_filter)
        return process_response(
            response,
            result_path='result.relationshipDefs.relationshipDef',
            require_unique=require_unique
        )

    def get_metadata_managed_object_defs(
            self,
            meta_adaptation,
            meta_class_abbreviation,
            meta_version,
            meta_content_selector='FULL'
    ):
        """
        Get managed objects metadata, where metadata means the description of CM object classes and parameters

        Example output (meta_content_selector=FULL)
        *******************************************
        ::

            {
                'metaClass': 'com.nokia.srbts.mnl:LUAC',
                'metaVersion': 'MNL25R2_2503_101',
                'pDef': {
                    'webEMSessionLogoutTimer': {
                        'constraint.default': '900',
                        'constraint.editing.create': 'mandatory',
                        'constraint.editing.update': 'optional',
                        'constraint.length.max': '0',
                        'constraint.length.min': '0',
                        'constraint.range.1.max': '7200',
                        'constraint.range.1.min': '120',
                        'constraint.range.1.step': '1',
                        'type': 'Integer',
                        'ui.conversion.range.1.divisor': '1',
                        'ui.conversion.range.1.multiplier': '1',
                        'ui.conversion.range.1.shift': '0.0',
                        'ui.description': 'Description 3',
                        'ui.name': 'WebEM session logout timer',
                        'ui.unit': 'Seconds'
                    }
                },
                'structListDef': {
                    'configurationTemplates': {
                        'constraint.editing.create': 'optional',
                        'constraint.editing.update': 'optional',
                        'constraint.size.max': '10',
                        'constraint.size.min': '0',
                        'ui.description': 'Description 1',
                        'ui.name': 'Configuration templates',
                        'itemDef': {
                            'pDef': {
                                'templateName': {
                                    'constraint.editing.create': 'optional',
                                    'constraint.editing.update': 'optional',
                                    'constraint.length.max': '255',
                                    'constraint.length.min': '0',
                                    'type': 'String',
                                    'ui.description': 'Description 2',
                                    'ui.name': 'Template name'
                                }
                            }
                        }
                    }
                }
            }

        :param string meta_adaptation: e.g. ``com.nokia.srbts.mnl``
        :param string meta_class_abbreviation: e.g. ``LUAC``
        :param string meta_version: e.g. ``MNL25R2_2503_101``
        :param string meta_content_selector: Meta content. Allowed values: ``BASIC`` or ``FULL``.
            For ``BASIC`` the output will contain only basic data about the specified managed object definition
            such as meta version, meta class abbreviation, and associated parameters.
            For ``FULL`` the output will contain extended information about all existing parameter details.
        :return: Managed objects metadata
        :rtype: dict
        """
        metadata_request_filter = self.soap_api.operations_type_factory.ManagedObjectDefFilter(
            metaAdaptation=meta_adaptation,
            metaClassAbbreviation=meta_class_abbreviation,
            metaVersion=meta_version,
            metaContentSelector=meta_content_selector)
        self.soap_api.service.getMetadata(metadata_request_filter)

        response_xml = self.soap_api.last_response(as_string=False)
        response_xml = remove_namespaces(response_xml, as_string=True)
        response_dict = convert_xml_to_dict(response_xml)
        response_dict = convert_metadata_response(response_dict)
        return process_response(
            response_dict['Envelope']['Body']['GetMetadataResponse'],
            result_path='result.managedObjectDefs.managedObjectDef',
            require_unique=True
        )
